var tabs = new StackPanel { Orientation = Orientation.Horizontal, Spacing = 4 };
foreach (var name in new[] { "inbox", "snoozed", "archive" })
{
    tabs.Children.Add(AppKit.Chip(FolderLabel(name), folder == name, () => SwitchFolder(name)));
}

var list = new StackPanel { Spacing = 8 };
foreach (var mail in mails)
{
    list.Children.Add(AppKit.Pressable(card: mail, expanded: expanded == mail.Id, open: () => Toggle(mail.Id)));
}

return AppKit.Screen(new StackPanel { Spacing = 10, Children = { tabs, list, undoHost } }, 560);
